# Let's look at the full raw lines to see if there's a label field
print("--- First 20 data lines with full content ---")
for i, line in enumerate(data_lines[:20]):
    print(f"{i}: {repr(line)}")

# Check if any lines have more than 3 fields when split by '||'
print("\n--- Checking for lines with more fields ---")
multi_field_lines = []
for line in data_lines:
    parts = line.split('||')
    if len(parts) > 3:
        multi_field_lines.append((len(parts), line))

print(f"Lines with more than 3 fields: {len(multi_field_lines)}")
if multi_field_lines:
    for count, line in multi_field_lines[:10]:
        print(f"Fields: {count}, Line: {repr(line)}")
